CAT = "ea1Taxation"; SEG = "TAX"
# Taxation (SEE Part 1 domain 4). Tax year 2025 unless stated. Computed keys asserted.
_niit = round(0.038 * min(50000, 230000 - 200000)); assert _niit == 1140
_addl = round(0.009 * (150000 + 150000 - 250000)); assert _addl == 450

Q = [
("In figuring alternative minimum taxable income, a taxpayer who used the standard deduction for regular tax:",
 "Adds the standard deduction back", ["Keeps the standard deduction", "Doubles the standard deduction", "Swaps it for itemized ones"],
 "The standard deduction is not allowed for the AMT, so it is added back on Form 6251. The AMT exemption takes its place."),
("The credit for prior year minimum tax on Form 8801 can arise from AMT that was caused by:",
 "Deferral items", ["Exclusion items only", "The standard deduction", "State income taxes"],
 "Only AMT from deferral items, timing differences such as depreciation or incentive stock option exercises, creates a minimum tax credit. AMT from exclusion items, such as the standard deduction, does not."),
("Which AMT adjustment is a timing difference that can reverse in later years?",
 "Depreciation on property", ["Tax-exempt private bond interest", "The standard deduction", "State and local taxes"],
 "Slower AMT depreciation makes the adjustment positive in early years and negative later. The other items are permanent exclusion items."),
("A household employer owes FUTA tax for 2025 if she paid total cash wages to household employees of at least what amount in any calendar quarter?",
 "$1,000", ["$2,800", "$1,500", "$2,000"],
 "Federal unemployment tax applies to household employers who paid $1,000 or more in cash wages in any quarter of the current or prior year."),
("Wages a parent pays her 19-year-old daughter to clean the family home are:",
 "Exempt from FICA", ["Subject to full FICA", "Subject to Medicare only", "Subject to FUTA only"],
 "Household wages paid to the employer's own child under 21 are not subject to Social Security and Medicare taxes. Wages to a spouse are also exempt."),
("A family hires a household employee and must file Schedule H and give a Form W-2. Before filing, the family needs:",
 "An employer identification number", ["A preparer tax ID number", "A Form 2441 from the worker", "A state business license number"],
 "A household employer reports wages on Form W-2 under an EIN, not the employer's Social Security number, and pays the taxes with Schedule H."),
("After withholding and refundable credits, a taxpayer owes $850 with her 2025 return. Her underpayment penalty is:",
 "None", ["The full penalty", "Half the usual penalty", "A flat $50"],
 "No estimated tax penalty applies when the tax owed after withholding and refundable credits is less than $1,000."),
("A client who will underpay estimated tax in December can cut the penalty most simply by:",
 "Raising wage withholding now", ["Paying in January instead", "Filing on October 15", "Skipping the Q4 payment"],
 "Withholding is treated as paid evenly through the year unless the taxpayer elects otherwise, so extra withholding late in the year covers earlier quarters. An estimated payment counts only from its date."),
("A taxpayer's income arrived mostly in December. To reduce the underpayment penalty on Form 2210 she can use:",
 "The annualized installment method", ["The prior-year safe harbor only", "The regular method only", "A Form 4868 extension of time"],
 "Schedule AI of Form 2210 annualizes income through each period, lowering required installments for income earned late in the year."),
("The IRS may waive the estimated tax penalty for a taxpayer who, in the year or the year before, retired after reaching age:",
 "62", ["55", "59 1/2", "60"],
 "Form 2210 allows a waiver for a taxpayer who retired after age 62 or became disabled in the tax year or prior year, when the underpayment was due to reasonable cause."),
("A farmer with two thirds of gross income from farming avoids the estimated tax penalty by filing and paying all tax by:",
 "March 1", ["April 15", "January 31", "June 15"],
 "Qualified farmers and fishermen can make one estimated payment by January 15 or skip it and file the return and pay all tax by March 1."),
("Interest the IRS charges on unpaid individual tax is figured at:",
 "Short-term rate plus 3%, daily", ["A flat 8% simple rate", "Prime rate plus 1%, yearly", "5% a month to 25%"],
 "The underpayment rate is the federal short-term rate plus 3 percentage points, set quarterly and compounded daily. The 5% a month figure is the failure-to-file penalty."),
("A church that elected out of FICA pays an employee wages. The employee owes self-employment tax if church employee income is at least:",
 "$108.28", ["$400.00", "$600.00", "$1,000.00"],
 "Church employee income of $108.28 or more is subject to self-employment tax. The usual $400 threshold applies to other self-employment income."),
("Fay's 2025 wages already reach the Social Security wage base. She also has net self-employment earnings. Her SE tax on those earnings is:",
 "Only the Medicare part", ["The full 15.3%", "Nothing at all", "Only the 12.4% part"],
 "Wages count toward the Social Security wage base first. Once it is reached, SE earnings owe only the 2.9% Medicare part, plus any additional Medicare tax."),
("A general partner's distributive share of a service partnership's ordinary business income is:",
 "Subject to self-employment tax", ["Exempt as investment income", "Subject to FUTA only", "Subject to NIIT only"],
 "A general partner's share of trade or business income is net earnings from self-employment. A limited partner's share is generally excluded, except guaranteed payments for services."),
("Two unrelated employers each withheld full Social Security tax on Leo's wages, so together they withheld more than the annual maximum. Leo:",
 "Claims it on his return", ["Gets it back from each employer", "Loses the excess", "Files Form 941-X"],
 "When excess Social Security tax results from two or more employers, the employee claims it as a credit on Schedule 3 of Form 1040."),
("A single employer withheld too much Social Security tax from Ava's wages. She should:",
 "Ask the employer to refund it", ["Claim it on Schedule 3", "Take it as a deduction", "Carry it to next year"],
 "Over-withholding by one employer is the employer's error to fix. If it does not, she can file Form 843 for a refund; it is not claimed as a credit on her return."),
("A married couple filing jointly checks for excess Social Security withholding. The calculation is done:",
 "Separately for each spouse", ["On their combined wages", "Only for the higher earner", "Only for the lower earner"],
 "Each spouse's withholding is compared with the wage base limit separately, even on a joint return."),
("A minister receives a $24,000 housing allowance used to pay for his home. For 2025 the allowance is:",
 "Subject to SE tax only", ["Fully taxable as wages", "Exempt from all taxes", "Subject to income tax only"],
 "A parsonage allowance used for housing is excluded from income tax, up to fair rental value, but it is included in net earnings from self-employment."),
("For Social Security and Medicare purposes, a minister performing ministerial services is generally:",
 "Self-employed", ["A common law employee", "Exempt with no election", "Covered by FUTA"],
 "Ministers are treated as self-employed for Social Security and Medicare on ministerial earnings and pay SE tax, even when the church treats them as employees for income tax."),
("A minister opposed on religious grounds to public insurance applies for exemption from SE tax on:",
 "Form 4361", ["Form 4029", "Form 8919", "Form 2106"],
 "Form 4361 must be filed by the due date, with extensions, of the return for the second year with $400 or more of net SE earnings, any part of it from ministerial services."),
("An enlisted soldier serves all year in a combat zone. Her military pay for that service is:",
 "Fully excluded from income", ["Excluded up to an officer cap", "Fully taxable", "Taxed at a lower rate"],
 "Enlisted members exclude all pay for months served in a combat zone. Commissioned officers exclude up to the highest enlisted rate plus imminent danger pay."),
("A service member leaves a combat zone. Filing and payment deadlines are extended for the time in the zone plus:",
 "180 days", ["90 days", "60 days", "1 year"],
 "Deadlines are extended for the period in the combat zone, plus 180 days after leaving it, plus the days that were left to act when the member entered."),
("A reservist travels more than 100 miles from home and stays overnight for a drill. Her unreimbursed travel costs are:",
 "Deductible for AGI", ["Not deductible at all", "Itemized, over 2% of AGI", "Only reimbursable"],
 "Armed forces reservists traveling over 100 miles and staying overnight deduct travel expenses as an adjustment on Form 2106, up to federal rates."),
("Ken inherits his late aunt's right to $15,000 of commissions she earned but had not received. The commissions are:",
 "Taxable to Ken when received", ["Tax-free as an inheritance", "Taxed only on her final return", "Stepped up to $0 gain"],
 "Income earned by a decedent but not received before death is income in respect of a decedent. It keeps its character and is taxed to whoever receives it, with no basis step-up."),
("A beneficiary reports income in respect of a decedent that was also in the taxable estate, which paid estate tax. The beneficiary may:",
 "Deduct the estate tax on it", ["Exclude the income", "Claim a refundable credit", "Spread it over 5 years"],
 "Section 691(c) gives a deduction for the federal estate tax attributable to the IRD, so the same item is not fully taxed twice."),
("Zoe, single, has MAGI of $230,000 including $50,000 of net investment income. Her net investment income tax is:",
 "$1,140", ["$1,900", "$874", "$7,600"],
 "NIIT is 3.8% of the lesser of net investment income ($50,000) or MAGI over $200,000 ($30,000): 3.8% x $30,000 = $1,140."),
("Which income is excluded from net investment income?",
 "IRA distributions", ["Rental income", "Capital gain on stock", "Taxable interest"],
 "Distributions from IRAs and qualified retirement plans, wages and self-employment income are not net investment income. Rents, interest, dividends and capital gains generally are."),
("For a married person filing separately, the net investment income tax applies to MAGI above:",
 "$125,000", ["$200,000", "$250,000", "$150,000"],
 "The thresholds are $250,000 married filing jointly, $125,000 married filing separately and $200,000 for single and head of household. They are not indexed."),
("An employer must withhold the 0.9% additional Medicare tax from an employee's wages above:",
 "$200,000", ["$100,000", "$125,000", "$150,000"],
 "Employers withhold the additional tax on wages over $200,000 paid to an employee in the year, whatever the employee's filing status."),
("A married couple filing jointly each earned $150,000 in wages from different employers. On Form 8959 they owe additional Medicare tax of:",
 "$450", ["$1,350", "$900", "$2,700"],
 "Their combined $300,000 exceeds the $250,000 joint threshold by $50,000, and 0.9% of that is $450. Neither employer withheld it because neither wage passed $200,000."),
("A waiter received $3,000 of cash tips he never reported to his employer. He pays Social Security and Medicare tax on them using:",
 "Form 4137", ["Form 8919", "Schedule H", "Form 8959"],
 "Form 4137 figures Social Security and Medicare tax on tips not reported to the employer. The tips are also wages for income tax."),
("A worker treated as a contractor believes she is an employee and got an SS-8 determination. She reports her share of FICA on:",
 "Form 8919", ["Schedule SE", "Form 4137", "Form 941"],
 "Form 8919 lets a misclassified employee pay only the employee's share of Social Security and Medicare tax instead of full SE tax."),
("Since 2010 Hal has repaid the 2008 first-time homebuyer credit in yearly installments, and he still lives in the home. On his 2025 return he repays:",
 "Nothing, as repayment ended", ["1/15 of the credit", "The whole unpaid balance", "1/10 of the credit"],
 "Credits for 2008 purchases were repaid in 15 equal installments on the 2010 through 2024 returns. The 2024 payment was the last one, and 2024 was the last year for Form 5405, so nothing is due for 2025."),
("Wen's 2024 AGI was $180,000 and she is single. To meet the prior-year safe harbor for 2025 estimated tax, her withholding and estimates must equal at least what share of her 2024 tax?",
 "110%", ["100%", "90%", "80%"],
 "A taxpayer whose prior-year AGI was over $150,000 ($75,000 married filing separately) must pay 110% of the prior year's tax, instead of 100%, to use the prior-year safe harbor. The other safe harbor is 90% of the current year's tax."),
("A taxpayer with a large ISO exercise wants to know if AMT applies. The form that compares tentative minimum tax with regular tax is:",
 "Form 6251", ["Form 8801", "Form 3921", "Form 8960"],
 "Form 6251 computes alternative minimum taxable income and tentative minimum tax. Form 8801 is used later to claim the minimum tax credit."),
]
